import React, { useState, useEffect } from "react";
import { Menu, X } from "lucide-react";

const links = [
  { label: "About", href: "#about" },
  { label: "Collections", href: "#collections" },
  { label: "Portfolio", href: "#portfolio" },
  { label: "Contact", href: "#contact" },
];

export default function Navbar({ onOpenQuote }) {
  const [scrolled, setScrolled] = useState(false);
  const [open, setOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 40);
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  return (
    <header className={`fixed top-0 inset-x-0 z-40 transition-all duration-500 ${scrolled ? "py-3 bg-white/95 backdrop-blur-xl shadow-lg" : "py-6 bg-transparent"}`} style={{ borderBottom: scrolled ? "1px solid rgba(212,175,55,0.2)" : "none" }}>
      <div className="flex items-center justify-between px-6 md:px-12 lg:px-24">
        <a href="#top" className="flex items-center gap-3">
          <span className="serif tracking-[0.2em] uppercase" style={{ fontSize: 16, color: "#d4af37", fontWeight: 500 }}>D Sajawat</span>
          <span className="hidden md:inline-block w-10 h-px" style={{ background: "rgba(212,175,55,0.5)" }} />
          <span className="hidden md:inline serif italic" style={{ color: "rgba(26,8,10,0.6)", fontSize: 13 }}>Premium Fabrics</span>
          <span className="hidden lg:inline-flex items-center gap-1 px-2 py-1 rounded-full text-[10px] font-semibold" style={{ background: "linear-gradient(135deg, #d4af37, #f4d77a)", color: "#1a080a" }}>
            ⭐ Since 2012
          </span>
        </a>
        <nav className="hidden md:flex items-center gap-9">
          {links.map((l) => (
            <a key={l.href} href={l.href} className="text-sm tracking-wider transition-colors hover:text-[#d4af37]" style={{ color: "rgba(26,8,10,0.7)" }}>{l.label}</a>
          ))}
          <button onClick={onOpenQuote} className="btn-gold" style={{ padding: "10px 22px", fontSize: 13 }}>Request Quote</button>
        </nav>
        <button className="md:hidden text-[#1a080a]" onClick={() => setOpen((s) => !s)}><Menu size={24} /></button>
      </div>
      {open && (
        <div className="md:hidden mx-6 mt-3 p-6 rounded-xl" style={{ background: "white", border: "1px solid rgba(212,175,55,0.3)", boxShadow: "0 8px 32px rgba(212,175,55,0.15)" }}>
          <div className="flex flex-col gap-4">
            {links.map((l) => (
              <a key={l.href} href={l.href} onClick={() => setOpen(false)} className="serif text-xl" style={{ color: "#1a080a" }}>{l.label}</a>
            ))}
            <button onClick={() => { setOpen(false); onOpenQuote(); }} className="btn-gold mt-2 self-start">Request Quote</button>
          </div>
        </div>
      )}
    </header>
  );
}
